"""Step media: video inserts generated by HeyGen Video (heygen-video-1), pipeline v4.

Every shot of storyboard.json with "media" and an English "prompt" whose file
videos/<slug>/media/<shot_id>.* does not exist yet is sent to
POST /v3/models/videos (text_to_video, 1:1 — the stage is 1080x1000), all jobs at once,
then polled and downloaded to media/<shot_id>.mp4. render_stage.js puts the file on the
stage (cover crop, clip sound dropped — the video has its own sound design).

media/heygen.json remembers {shot_id: {prompt, video_id, ...}}: a re-run picks up a job
that is still running instead of paying again, and a changed prompt makes a new clip
(only for clips this step made; a file you put there by hand is never touched).

No HeyGen key or no media shots: nothing to do. Only the standard library is used.
Env: HEYGEN_API_KEY (or VIDEO_BACKEND_HEYGEN_API_KEY); MEDIA_RES 768p|1080p (default 768p);
MEDIA_MAX — at most this many new clips per run (default 8); MEDIA_ENHANCE quality|turbo (default quality).
"""
import hashlib, json, math, os, time, urllib.error, urllib.request
from common import VIDEO

API = os.environ.get("HEYGEN_API_URL", "https://api.heygen.com")
KEY = os.environ.get("HEYGEN_API_KEY") or os.environ.get("VIDEO_BACKEND_HEYGEN_API_KEY") or ""
RES = os.environ.get("MEDIA_RES", "768p")
MAX_NEW = int(os.environ.get("MEDIA_MAX", "8"))
ENHANCE = os.environ.get("MEDIA_ENHANCE", "quality")
RATE = {"480p": 0.0106, "768p": 0.019, "1080p": 0.053, "2k": 0.053}  # ~$ per second, text_to_video (estimate)
MEDIA = os.path.join(VIDEO, "media")
BOOK = os.path.join(MEDIA, "heygen.json")
EXTS = ("mp4", "mov", "webm", "png", "jpg", "jpeg", "webp")
STYLE = (" Square 1:1 frame, main subject centred and large, slow steady camera move. Photorealistic, natural light."
         " No readable text, no logos, no captions, no watermarks; screens heavily blurred; people generic and"
         " unrecognizable. Soft ambient sound only, no music, no speech.")


def call(method, path, body=None, headers=None):
    req = urllib.request.Request(API + path, method=method, data=json.dumps(body).encode() if body is not None else None,
                                 headers={"x-api-key": KEY, "Content-Type": "application/json", **(headers or {})})
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            return json.loads(r.read())
    except urllib.error.HTTPError as e:
        raise RuntimeError(f"HeyGen {method} {path}: {e.code} {e.read()[:300]!r}") from None


def download(url, out):
    """The clip from HeyGen's storage: through the outbound proxy first when there is one (the lab server's
    direct route stalls — 31.10 every direct try timed out), then direct with a short timeout."""
    proxy = os.environ.get("HEYGEN_DOWNLOAD_PROXY") or os.environ.get("VIDEO_BACKEND_OPENROUTER_PROXY_URL") or ""
    for via in ([proxy] * 2 if proxy else []) + [None]:
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({"https": via, "http": via} if via else {}))
        try:
            with opener.open(url, timeout=180 if via else 45) as r, open(out + ".part", "wb") as f:
                while chunk := r.read(1 << 20):
                    f.write(chunk)
            os.replace(out + ".part", out)
            return True
        except Exception as e:  # noqa: BLE001
            print(f"    download {'via proxy' if via else 'direct'} failed: {e}")
            time.sleep(2)
    return False


def existing(sid):
    return next((os.path.join(MEDIA, f"{sid}.{x}") for x in EXTS if os.path.exists(os.path.join(MEDIA, f"{sid}.{x}"))), None)


def main():
    sb_path = os.path.join(VIDEO, "storyboard.json")
    tm_path = os.path.join(VIDEO, "build", "timing.json")
    if not os.path.exists(sb_path):
        print("media: no storyboard.json"); return
    sb = json.load(open(sb_path, encoding="utf-8"))
    timing = {s["id"]: s for s in json.load(open(tm_path))["shots"]} if os.path.exists(tm_path) else {}
    slots = []
    for sc in sb:
        for j, sh in enumerate(sc.get("shots") or []):
            m = sh.get("media")
            if isinstance(m, dict) and (m.get("prompt") or "").strip():
                sid = sh.get("id") or f"{sc['scene']}_{j + 1}"
                t = timing.get(sid)
                dur = (t["t1"] - t["t0"]) if t else float(m.get("seconds") or 5)
                slots.append((sid, m["prompt"].strip(), max(5, min(15, math.ceil(dur + 0.3)))))
    if not slots:
        print("media: no generation slots"); return
    if not KEY:
        print(f"media: {len(slots)} slot(s), no HEYGEN_API_KEY — placeholders stay"); return
    os.makedirs(MEDIA, exist_ok=True)
    book = json.load(open(BOOK)) if os.path.exists(BOOK) else {}
    todo = []
    for sid, prompt, secs in slots:
        f, rec = existing(sid), book.get(sid)
        if f and not (rec and rec.get("prompt") != prompt and rec.get("file") == os.path.basename(f)):
            continue  # a file is there (hand-made, or ours for this same prompt)
        if f:
            os.remove(f)  # ours, but the director changed the prompt
        todo.append((sid, prompt, secs))
    if not todo:
        print(f"media: all {len(slots)} slot(s) have files"); return
    if len(todo) > MAX_NEW:
        print(f"media: {len(todo)} new clips wanted, MEDIA_MAX={MAX_NEW} — the rest stay placeholders")
        todo = todo[:MAX_NEW]
    est = sum(s for _, _, s in todo) * RATE.get(RES, 0.053)
    print(f"media: generating {len(todo)} clip(s), {RES}, ~${est:.2f}")
    jobs = {}
    for sid, prompt, secs in todo:
        rec = book.get(sid) or {}
        if rec.get("prompt") == prompt and rec.get("video_id") and rec.get("status") not in ("failed", "cancelled"):
            jobs[sid] = rec["video_id"]; continue  # still running from the previous run
        body = {"model": "heygen-video-1", "mode": "text_to_video", "prompt": prompt.rstrip(" .") + "." + STYLE, "duration": secs,
                "resolution": RES, "aspect_ratio": "1:1", "prompt_enhancement": ENHANCE}
        idem = hashlib.sha1(json.dumps([VIDEO, sid, body], sort_keys=True).encode()).hexdigest()[:32]
        try:
            vid = call("POST", "/v3/models/videos", body, {"Idempotency-Key": idem})["data"]["video_id"]
        except Exception as e:  # noqa: BLE001 — one bad slot must not stop the others
            print(f"  {sid}: not started — {e}"); continue
        jobs[sid] = vid
        book[sid] = {"prompt": prompt, "video_id": vid, "seconds": secs, "res": RES, "status": "pending"}
        json.dump(book, open(BOOK, "w"), ensure_ascii=False, indent=1)
        print(f"  {sid}: started {vid} ({secs} s)")
    deadline = time.time() + float(os.environ.get("MEDIA_TIMEOUT", "1800"))
    while jobs and time.time() < deadline:
        time.sleep(float(os.environ.get("MEDIA_POLL", "15")))
        for sid, vid in list(jobs.items()):
            try:
                d = call("GET", f"/v3/models/videos/{vid}")["data"]
            except Exception as e:  # noqa: BLE001
                print(f"  {sid}: poll failed — {e}"); continue
            st = d.get("status")
            if st == "completed":
                out = os.path.join(MEDIA, sid + ".mp4")
                if not download(d["video_url"], out):
                    print(f"  {sid}: download failed, will retry on the next poll"); continue
                book[sid].update(status="completed", file=sid + ".mp4", width=d.get("width"), height=d.get("height"))
                print(f"  {sid}: done {d.get('width')}x{d.get('height')}, {d.get('duration')} s")
                del jobs[sid]
            elif st in ("failed", "cancelled"):
                book[sid].update(status=st, error=d.get("failure_message"))
                print(f"  {sid}: {st} — {d.get('failure_message')}")
                del jobs[sid]
        json.dump(book, open(BOOK, "w"), ensure_ascii=False, indent=1)
    for sid in jobs:
        print(f"  {sid}: still running — re-run the step later (`--from media`), it will be picked up without paying again")
    done = sum(1 for sid, _, _ in slots if existing(sid))
    print(f"media: {done}/{len(slots)} slot(s) have clips")


if __name__ == "__main__":
    main()
